import { useEffect } from 'react'

export default function Testimonials() {
  useEffect(() => {
    const section = document.querySelector('.framer-1gx9988')
    if (!section) return

    const cards = [
      { el: section.querySelector('.framer-18hgfpp'), base: 'translate(-50%, -50%) translateX(240px) translateY(-106px) rotate(6deg)', speed: 0.15 },
      { el: section.querySelector('.framer-6idmd8'), base: 'translate(-50%, -50%) translateX(142px) translateY(-43px) rotate(-7deg)', speed: -0.2 },
      { el: section.querySelector('.framer-1j99ufo'), base: 'translate(-50%, -50%) translateX(53px) translateY(131px) rotate(-5deg)', speed: 0.25 },
      { el: section.querySelector('.framer-1q8094n'), base: 'translate(-50%, -50%) translateX(-265px) translateY(53px) rotate(9deg)', speed: -0.15 },
      { el: section.querySelector('.framer-1k18mro'), base: 'translate(-50%, -50%) translateX(-62px) translateY(-40px) rotate(-16deg)', speed: 0.18 }
    ].filter(c => c.el)

    // Initial state
    cards.forEach((c, idx) => {
      c.el.style.opacity = '0'
      c.el.style.transform = `${c.base} scale(0.9)`
      c.el.style.transition = `opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1) ${idx * 0.1}s, transform 0.8s cubic-bezier(0.16, 1, 0.3, 1) ${idx * 0.1}s`
    })

    let isRevealed = false
    const observer = new IntersectionObserver((entries) => {
      entries.forEach(entry => {
        if (entry.isIntersecting) {
          isRevealed = true
          cards.forEach(c => {
            c.el.style.opacity = '1'
            c.el.style.transform = c.base
          })
          observer.disconnect()
        }
      })
    }, { threshold: 0.1 })

    observer.observe(section)

    // Scroll by movement parallax
    const handleScroll = () => {
      if (!isRevealed) return
      const rect = section.getBoundingClientRect()
      const winHeight = window.innerHeight
      if (rect.top < winHeight && rect.bottom > 0) {
        const progress = (winHeight - rect.top) / (winHeight + rect.height) - 0.5
        cards.forEach(c => {
          const shiftY = progress * c.speed * 80
          c.el.style.transform = `${c.base} translate3d(0, ${shiftY}px, 0)`
          c.el.style.transition = 'transform 0.1s ease-out'
        })
      }
    }

    window.addEventListener('scroll', handleScroll, { passive: true })
    return () => {
      observer.disconnect()
      window.removeEventListener('scroll', handleScroll)
    }
  }, [])

  return (
    <section
      className="framer-1gx9988"
      data-framer-name="Testimonials"
      dangerouslySetInnerHTML={{ __html: content }}
    />
  )
}

